begin;
select plan(29);
select has_table('app_private','communication_templates','versioned templates exist');
select has_table('app_private','communication_intents','immutable intents exist');
select has_table('app_private','communication_attempts','durable attempts exist');
select has_table('app_private','inbound_messages','normalized inbound messages exist');
select has_table('app_private','communication_provider_health','provider health exists');
select has_function('api','communication_create_intent',array['uuid','jsonb','uuid','text'],'intent command exists');
insert into auth.users(id,email)values('81000000-0000-4000-8000-000000000001','communications-office@test.invalid'),('81000000-0000-4000-8000-000000000002','communications-driver@test.invalid'),('81000000-0000-4000-8000-000000000003','communications-other@test.invalid');
insert into public.user_profiles(user_id,display_name)values('81000000-0000-4000-8000-000000000001','Communications Office'),('81000000-0000-4000-8000-000000000002','Communications Driver'),('81000000-0000-4000-8000-000000000003','Other Region');
insert into app_private.user_roles(user_id,role_id)select'81000000-0000-4000-8000-000000000001'::uuid,role_id from app_private.roles where role_key='director_admin' union all select'81000000-0000-4000-8000-000000000002'::uuid,role_id from app_private.roles where role_key='driver_team' union all select'81000000-0000-4000-8000-000000000003'::uuid,role_id from app_private.roles where role_key='office_admin';
insert into app_private.user_access_scopes(user_id,scope_kind,scope_id)values('81000000-0000-4000-8000-000000000001','global',null),('81000000-0000-4000-8000-000000000003','service_region',gen_random_uuid());
insert into app_private.client_contacts(client_contact_id,client_id,contact_name,mobile_e164,email,is_primary)values('82000000-0000-4000-8000-000000000001','57000000-0000-0000-0000-000000000001','Synthetic Recipient','+27820000001','recipient@example.invalid',true);
select is((app_private.communication_eligibility('57000000-0000-0000-0000-000000000001','test_message')->>'recipientAvailable')::boolean,true,'authoritative contact resolved');
select is(app_private.communication_eligibility('57000000-0000-0000-0000-000000000001','test_message')->'eligibleChannels','["whatsapp","sms","email"]'::jsonb,'fallback order is provider neutral');
select is((api.communication_create_intent('81000000-0000-4000-8000-000000000001','{"communicationType":"test_message","clientId":"57000000-0000-0000-0000-000000000001","sourceDomain":"manual","sourceReference":"test-1","templateKey":"test_message","templateVersion":1,"variables":{"clientName":"Synthetic Recipient"}}',gen_random_uuid(),'occurrence-1')->>'lifecycle_status'),'ready','intent created ready');
select is((select count(*)from app_private.communication_intents),1::bigint,'one intent persisted');
select lives_ok($$select api.communication_create_intent('81000000-0000-4000-8000-000000000001','{"communicationType":"test_message","clientId":"57000000-0000-0000-0000-000000000001","sourceDomain":"manual","sourceReference":"test-1","templateKey":"test_message","templateVersion":1,"variables":{"clientName":"Synthetic Recipient"}}',gen_random_uuid(),'occurrence-1')$$,'duplicate intent returns safely');
select is((select count(*)from app_private.communication_intents),1::bigint,'duplicate intent does not duplicate send identity');
select lives_ok($$select api.communication_record_attempt((select communication_intent_id from app_private.communication_intents),'whatsapp','fake-communications','{"contactId":"82000000-0000-4000-8000-000000000001","destination":"protected"}','', 'Synthetic message','accepted','fake-wa-1',null,0,gen_random_uuid())$$,'WhatsApp attempt recorded');
select is((select channel from app_private.communication_attempts),'whatsapp','WhatsApp is first attempt');
select is((api.communication_delivery_callback('fake-communications','fake-wa-1','delivered',now())->>'lifecycle_status'),'delivered','delivery callback advances status');
select is((api.communication_delivery_callback('fake-communications','fake-wa-1','sent',now()-interval'1 minute')->>'lifecycle_status'),'delivered','out-of-order callback cannot regress delivered');
select lives_ok($$select api.communication_delivery_callback('fake-communications','fake-wa-1','delivered',now())$$,'duplicate callback is safe');
select is((api.communication_ingest_inbound('fake-communications','whatsapp','inbound-1','+27820000001',now(),' SKIP ',gen_random_uuid())->>'recognized_command'),'skip','SKIP recognized case-insensitively');
select is((select match_classification from app_private.inbound_messages),'matched','inbound sender matched');
select lives_ok($$select api.communication_ingest_inbound('fake-communications','whatsapp','inbound-1','+27820000001',now(),'SKIP',gen_random_uuid())$$,'duplicate inbound is safe');
select is((select count(*)from app_private.inbound_messages),1::bigint,'inbound duplicate not duplicated');
select is((select count(*)from app_private.route_operations),0::bigint,'SKIP recognition performs no route action');
select is((select count(*)from app_private.client_services),3::bigint,'SKIP recognition performs no service action');
insert into app_private.communication_suppressions(client_contact_id,channel,reason)values('82000000-0000-4000-8000-000000000001','whatsapp','synthetic opt out');
select is(app_private.communication_eligibility('57000000-0000-0000-0000-000000000001','test_message')->'eligibleChannels','["sms","email"]'::jsonb,'suppressed channel is not eligible');
select throws_ok($$select api.communication_list('81000000-0000-4000-8000-000000000002','{}')$$,'42501',null,'Driver communications access denied');
select is((api.communication_list('81000000-0000-4000-8000-000000000003','{}')->'items'),'[]'::jsonb,'cross-region list is empty');
select throws_ok('set local role authenticated;select * from app_private.communication_intents','42501',null,'browser direct reads denied');
select ok((select count(*)>=1 from app_private.business_audit_facts where module_key='communications'),'human send audited');
select ok((select count(*)>=3 from app_private.outbox_events where producer_module='communications'),'safe communications events emitted');
select * from finish();rollback;
